using AlshrouqSchool.Domain.Contracts; using AlshrouqSchool.Domain.Entities.MediaAndContentModule; using AlshrouqSchool.Shared.DTOs.Gallery.Media; using AutoMapper; using MediatR;
namespace AlshrouqSchool.Application.Features.Gallery.Commands.Media;
public sealed record CreateMediaCommand(CreateMediaDto Dto) : IRequest<MediaDto>; public sealed record UpdateMediaCommand(int Id, UpdateMediaDto Dto) : IRequest<MediaDto>; public sealed record DeleteMediaCommand(int Id) : IRequest<bool>;
public sealed class CreateMediaCommandHandler(IUnitOfWork unitOfWork,IMapper mapper):IRequestHandler<CreateMediaCommand,MediaDto>{ public async Task<MediaDto> Handle(CreateMediaCommand r,CancellationToken ct){var e=mapper.Map<Media>(r.Dto); await unitOfWork.GetRepository<Media,int>().AddAsync(e); await unitOfWork.SAveChangesAsync(ct); return mapper.Map<MediaDto>(e);}}
public sealed class UpdateMediaCommandHandler(IUnitOfWork unitOfWork,IMapper mapper):IRequestHandler<UpdateMediaCommand,MediaDto>{ public async Task<MediaDto> Handle(UpdateMediaCommand r,CancellationToken ct){var repo=unitOfWork.GetRepository<Media,int>();var e=await repo.GetByIdAsync(r.Id)??throw new KeyNotFoundException("Media was not found.");if(e.IsDeleted)throw new KeyNotFoundException("Media was not found.");mapper.Map(r.Dto,e);repo.Update(e);await unitOfWork.SAveChangesAsync(ct);return mapper.Map<MediaDto>(e);}}
public sealed class DeleteMediaCommandHandler(IUnitOfWork unitOfWork):IRequestHandler<DeleteMediaCommand,bool>{public async Task<bool> Handle(DeleteMediaCommand r,CancellationToken ct){var repo=unitOfWork.GetRepository<Media,int>();var e=await repo.GetByIdAsync(r.Id);if(e is null||e.IsDeleted)return false;e.IsDeleted=true;e.DeletedAtUtc=DateTime.UtcNow;repo.Update(e);await unitOfWork.SAveChangesAsync(ct);return true;}}